@IsTest private class ClassAccessContract {
 @IsTest static void enabledDeclarationProjectsParent(){
  PermissionSet grant=[SELECT Id FROM PermissionSet WHERE Name='DeclaredAccess'];
  ApexClass target=[SELECT Id FROM ApexClass WHERE Name='EnabledEndpoint'];
  List<SetupEntityAccess> links=[SELECT ParentId,SetupEntityId,SetupEntityType FROM SetupEntityAccess WHERE ParentId=:grant.Id AND SetupEntityId=:target.Id];
  System.assertEquals(1,links.size());System.assertEquals(grant.Id,links[0].ParentId);System.assertEquals(target.Id,links[0].SetupEntityId);System.assertEquals('ApexClass',links[0].SetupEntityType);
 }
 @IsTest static void enabledChildRelationship(){
  ApexClass target=[SELECT Name,(SELECT ParentId FROM SetupEntityAccessItems) FROM ApexClass WHERE Name='EnabledEndpoint'];
  System.assertEquals(1,target.SetupEntityAccessItems.size());
  PermissionSet grant=[SELECT Id FROM PermissionSet WHERE Name='DeclaredAccess'];System.assertEquals(grant.Id,target.SetupEntityAccessItems[0].ParentId);
 }
 @IsTest static void disabledDeclarationControl(){
  ApexClass target=[SELECT Id FROM ApexClass WHERE Name='DisabledEndpoint'];System.assertEquals(0,[SELECT Id FROM SetupEntityAccess WHERE SetupEntityId=:target.Id].size());
 }
 @IsTest static void noAutomaticAssignmentControl(){
  PermissionSet grant=[SELECT Id FROM PermissionSet WHERE Name='DeclaredAccess'];System.assertEquals(0,[SELECT Id FROM PermissionSetAssignment WHERE PermissionSetId=:grant.Id].size());
 }
}
